sklearn roadmap
```
flowchart TD
    START([START]) --> ProblemType{预测问题类型}
    
    %% ========== 分类分支 ==========
    ProblemType -- 分类 --> ClassSampleCount{样本数 > 50?}
    ClassSampleCount -- 是 --> ClassFeatureCount{特征数 > 1e5?}
    ClassFeatureCount -- 是 --> Linearsvc["LinearSVC\n(线性核)"]
    ClassFeatureCount -- 否 --> TextData{文本数据?}
    TextData -- 是 --> NB["Naive Bayes\n(朴素贝叶斯)"]
    TextData -- 否 --> KNNcls["KNeighborsClassifier\n(K近邻)"]
    ClassSampleCount -- 否 --> ClassCategory{预测类别?}
    ClassCategory -- 否 --> Outlier{离群检测?}
    ClassCategory -- 是 --> SampleOver10K{样本 > 10,000?}
    SampleOver10K -- 是 --> SVC["SVC\n(核方法)"]
    SampleOver10K -- 否 --> Ensemble["Ensemble Classifiers\n(集成方法)"]
    
    %% ========== 回归分支 ==========
    ProblemType -- 回归 --> RegSampleCount{样本 > 100,000?}
    RegSampleCount -- 是 --> SGD["SGDRegressor"]
    RegSampleCount -- 否 --> FeatureCount{特征数 > 100,000?}
    FeatureCount -- 是 --> Elastic["ElasticNet"]
    FeatureCount -- 否 --> PredictCategoryY{预测类别?}
    PredictCategoryY -- 是 --> Lasso["Lasso"]
    PredictCategoryY -- 否 --> EnsembleReg{样本 > 10,000?}
    EnsembleReg -- 是 --> KernelRidge["Kernel Ridge"]
    EnsembleReg -- 否 --> ForestReg["RandomForestRegressor"]
    
    %% ========== 聚类分支 ==========
    ProblemType -- 聚类 --> KnownClassNum{已知类别数?}
    KnownClassNum -- 是 --> SampleOver10Kc{样本 > 10,000?}
    SampleOver10Kc -- 是 --> MiniBatch["MiniBatchKMeans"]
    SampleOver10Kc -- 否 --> Kmeans["KMeans"]
    KnownClassNum -- 否 --> ClusterAlgo{类别估计?}
    ClusterAlgo -- 密度估计 --> MeanShift["MeanShift"]
    ClusterAlgo -- 图聚类 --> Spectral["Spectral Clustering"]
    ClusterAlgo -- 高斯混合 --> GMM["Gaussian Mixture"]
    
    %% ========== 降维分支 ==========
    ProblemType -- 降维 --> Visualization{可视化?}
    Visualization -- 是 --> TSNE["TSNE"]
    Visualization -- 否 --> FeatureNumD{特征 > 100?}
    FeatureNumD -- 是 --> FeatureAgg["FeatureAgglomeration"]
    FeatureNumD -- 否 --> LDA["LDA\n(线性判别)"]

    %% ======= 特殊连接器 =======
    ClassSampleCount -- ">50K样本" ----> Linearsvc
    Ensemble -.-> NextClass["Next: NN\n或其它模型"]
    
    %% ====== 区域颜色标记 ======
    classDef classification fill:#F9C,stroke:#333;
    classDef regression fill:#9CF,stroke:#333;
    classDef clustering fill:#F8F,stroke:#333;
    classDef reduction fill:#FFD,stroke:#333;
    
    class START classification
    class ClassSampleCount,ClassFeatureCount,TextData,ClassCategory,Outlier,SampleOver10K classification
    class RegSampleCount,FeatureCount,PredictCategoryY,EnsembleReg regression
    class KnownClassNum,SampleOver10Kc,ClusterAlgo clustering
    class Visualization,FeatureNumD reduction

